const pool = new pg.Pool({ connectionString: process.env.DATABASE_URL });
try {
  await pool.query(
    `INSERT INTO bookings (room_id, user_id, starts_at, ends_at, attendees)
     VALUES ($1, $2, $3, $4, $5)`,
    [99, 1, new Date("2026-10-07T09:00:00Z"), new Date("2026-10-07T10:00:00Z"), 2],
  );
} catch (err) {
  if (!(err instanceof pg.DatabaseError)) throw err;
  console.log({ code: err.code, constraint: err.constraint, detail: err.detail });
}
await pool.end();

